def test_wrapped_function_still_works():
    @count_calls
    def add(a, b):
        return a + b
    assert add(2, 3) == 5, 'the decorated function must still return the original result'

def test_counts_every_call():
    @count_calls
    def ping():
        return 'pong'
    ping()
    ping()
    ping()
    assert ping.calls == 3, 'calls must be counted across every invocation'

def test_preserves_function_name():
    @count_calls
    def greet():
        return 'hi'
    assert greet.__name__ == 'greet', 'functools.wraps must preserve the original __name__'

